package cn.ngapure.app;

import android.content.SharedPreferences;
import java.io.IOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public final class NativeUserBlocksTest {
    private static int checks;
    private static void ok(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    private static final class Memory implements SharedPreferences {
        final Map<String,Object> values=new HashMap<>();boolean reject;
        public Map<String,?> getAll(){return new HashMap<>(values);}public String getString(String key,String fallback){return values.containsKey(key)?(String)values.get(key):fallback;}public Set<String> getStringSet(String key,Set<String> fallback){return fallback;}public int getInt(String key,int fallback){return fallback;}public long getLong(String key,long fallback){return fallback;}public float getFloat(String key,float fallback){return fallback;}public boolean getBoolean(String key,boolean fallback){return fallback;}public boolean contains(String key){return values.containsKey(key);}public void registerOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener listener){}public void unregisterOnSharedPreferenceChangeListener(OnSharedPreferenceChangeListener listener){}
        public Editor edit(){return new Editor(){final Map<String,Object> put=new HashMap<>();final Set<String> removed=new HashSet<>();boolean clear;public Editor putString(String key,String value){put.put(key,value);return this;}public Editor putStringSet(String key,Set<String> value){put.put(key,value);return this;}public Editor putInt(String key,int value){put.put(key,value);return this;}public Editor putLong(String key,long value){put.put(key,value);return this;}public Editor putFloat(String key,float value){put.put(key,value);return this;}public Editor putBoolean(String key,boolean value){put.put(key,value);return this;}public Editor remove(String key){removed.add(key);return this;}public Editor clear(){clear=true;return this;}public boolean commit(){if(reject)return false;apply();return true;}public void apply(){if(clear)values.clear();for(String key:removed)values.remove(key);values.putAll(put);}};}
    }
    private interface Action{void run() throws Exception;}
    private static void fails(Action action,String label) throws Exception {try{action.run();throw new AssertionError(label);}catch(IOException|IllegalArgumentException expected){checks++;}}
    public static void main(String[] ignored) throws Exception {
        Memory memory=new Memory();NativeUserBlockStore one=new NativeUserBlockStore(memory,"bbs.nga.cn","70001");ok(one.users().isEmpty()&&memory.values.isEmpty(),"constructors and reads do not write");one.set("70002","fixture用户",true,()->true);ok(one.users().size()==1&&one.users().get(0).name.equals("fixture用户"),"explicit local block persisted");ok(new NativeUserBlockStore(memory,"bbs.nga.cn","70001").users().size()==1,"cold reconstruction retains local block");ok(new NativeUserBlockStore(memory,"ngabbs.com","70001").users().isEmpty(),"host isolated");ok(new NativeUserBlockStore(memory,"bbs.nga.cn","70003").users().isEmpty(),"account isolated");String key=memory.values.keySet().iterator().next();ok(!key.contains("70001")&&!key.contains("bbs.nga.cn"),"scope identity is hashed");ok(!memory.values.toString().contains("cookie")&&!memory.values.toString().contains("token"),"no session data stored");one.set("70002","renamed",true,()->true);ok(one.users().size()==1&&one.users().get(0).name.equals("renamed"),"same UID update does not duplicate");fails(()->one.set("70001","self",true,()->true),"self block rejected");fails(()->one.set("70005","x",true,()->false),"scope changed before commit rejected");ok(one.users().size()==1,"account change cannot add block");memory.reject=true;fails(()->one.set("70005","x",true,()->true),"failed commit not reported as saved");memory.reject=false;one.set("70002","renamed",false,()->true);ok(one.users().isEmpty(),"explicit unblock removes filter");memory.values.put(key,"{broken");ok(one.users().isEmpty(),"damaged local list never hides random authors");fails(()->one.set("70002","x",true,()->true),"corrupt data cannot be silently overwritten");one.clear(()->true);ok(one.users().isEmpty()&&!memory.values.containsKey(key),"explicit clear recovers corrupt list without touching other scopes");one.set("70002","x",true,()->true);fails(()->one.clear(()->false),"switched scope cannot clear local blocks");ok(one.users().size()==1,"rejected clear retains block");fails(()->new NativeUserBlockStore(memory,"evil.test","70001"),"unknown host rejected");fails(()->new NativeUserBlockStore(memory,"bbs.nga.cn",""),"anonymous scope rejected");System.out.println("NativeUserBlocksTest: "+checks+" local persistence checks passed; no network or device.");
    }
}
